impl Default for Parameters {
	fn default() -> Self {
		*Self::new_box()
	}
}

#[inline]
fn read_parameter_slot(parameters: &Parameters, index: usize) -> f64 {
	debug_assert!(index < PARAMETER_DISPLAY_NAMES.len(), "generated parameter index out of range");
	parameters.values[index]
}

fn validate_parameter_scalar_metadata(index: usize, value: f64) -> Result<(), String> {
	let Some(&name) = PARAMETER_DISPLAY_NAMES.get(index) else {
		return Err(format!("generated parameter index {} is out of range", index));
	};
	let flags = PARAMETER_RANGE_FLAGS[index];
	validate_finite_parameter(name, value)?;
	if PARAMETER_INTEGER_FLAGS[index] && value.fract() != 0.0 {
		return Err(format!("parameter '{}' must be an integer, got {}", name, value));
	}
	if PARAMETER_INTEGER_FLAGS[index] && (value < i32::MIN as f64 || value > i32::MAX as f64) {
		return Err(format!("parameter '{}' must fit in a 32-bit signed integer, got {}", name, value));
	}
	validate_parameter_bound_indices(
		name,
		value,
		flags,
		&PARAMETER_BOUND_POOL,
		PARAMETER_MIN_BOUNDS[index],
		PARAMETER_MAX_BOUNDS[index],
		PARAMETER_EXCLUDED_BOUNDS[index],
	)
}

fn validate_parameter_metadata(
	parameters: &Parameters,
	index: usize,
	value: f64,
) -> Result<(), String> {
	validate_parameter_scalar_metadata(index, value)?;
	let name = PARAMETER_DISPLAY_NAMES[index];
	let flags = PARAMETER_RANGE_FLAGS[index];
	let static_min = resolve_parameter_bound(&PARAMETER_BOUND_POOL, PARAMETER_MIN_BOUNDS[index]);
	let static_max = resolve_parameter_bound(&PARAMETER_BOUND_POOL, PARAMETER_MAX_BOUNDS[index]);
	let computed_min = parameter_computed_min_bound(parameters, index)?;
	let lower_source_count = usize::from(static_min.is_some())
		+ usize::from(PARAMETER_MIN_REFERENCES[index].is_some())
		+ usize::from(computed_min.is_some());
	if lower_source_count > 1 {
		return Err(format!("parameter '{}' has conflicting lower-bound sources", name));
	}
	let min = match PARAMETER_MIN_REFERENCES[index] {
		Some(reference) => Some(parameter_bound_from_reference(parameters, reference)?),
		None => computed_min.or(static_min),
	};
	let computed_max = parameter_computed_max_bound(parameters, index)?;
	let upper_source_count = usize::from(static_max.is_some())
		+ usize::from(PARAMETER_MAX_REFERENCES[index].is_some())
		+ usize::from(computed_max.is_some());
	if upper_source_count > 1 {
		return Err(format!("parameter '{}' has conflicting upper-bound sources", name));
	}
	let max = match PARAMETER_MAX_REFERENCES[index] {
		Some(reference) => Some(parameter_bound_from_reference(parameters, reference)?),
		None => computed_max.or(static_max),
	};
	if let (Some(min), Some(max)) = (min, max) {
		let empty = min.value > max.value
			|| (min.value == max.value
				&& flags & (PARAMETER_MIN_EXCLUSIVE_FLAG | PARAMETER_MAX_EXCLUSIVE_FLAG) != 0);
		if empty {
			return Err(format!(
				"parameter '{}' has an empty range: lower bound {}={} exceeds upper bound {}={}",
				name, min.label, min.value, max.label, max.value
			));
		}
	}
	validate_parameter_bounds(name, value, flags, min, max, &[])?;
	for &reference in PARAMETER_EXCLUDED_REFERENCES[index] {
		let excluded = parameter_bound_from_reference(parameters, reference)?;
		if value == excluded.value {
			return Err(format!(
				"parameter '{}' must not equal {}={}, got {}",
				name, excluded.label, excluded.value, value
			));
		}
	}
	validate_parameter_computed_exclusions(parameters, index, value)?;
	Ok(())
}

fn parameter_bound_from_reference(
	parameters: &Parameters,
	index: usize,
) -> Result<ParameterBound, String> {
	let Some(&name) = PARAMETER_DISPLAY_NAMES.get(index) else {
		return Err(format!("generated parameter range reference {} is out of range", index));
	};
	let value = read_parameter_slot(parameters, index);
	validate_finite_parameter(name, value)?;
	Ok(ParameterBound { value, label: name })
}


